/*
 * Pro tips
 * - Use half-open ranges [start, end); a range of length 0 or 1 is already sorted.
 * - Recursively sort both halves before merging; each pointer tracks the next unused value in its half.
 * - The merge continues while EITHER half has values. Check exhaustion before accessing either list.
 * - Choose the left value on ties (<=) to preserve stability, and advance only the pointer you consumed.
 * - This version returns a new merged list rather than copying results back into the input.
 * - Base-case subList results are views of the original list; a size-0/1 result can alias the input.
 * - O(n log n) time and O(n) peak live auxiliary space, with O(log n) recursion depth.
 * - New merge lists allocate O(n log n) element slots over the whole run; a reusable buffer reduces allocations.
 * - Check empty, singleton, odd-sized, duplicate, and reverse-sorted inputs.
 */

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;

class Solution {
    public static List<Integer> sortListInterval(List<Integer> unsortedList, int start, int end) {
        // Base case: A list of size 1 or 0 is already sorted
        if (end - start <= 1) {
            return unsortedList.subList(start, end);
        }

        // Split the list into left and right halves
        int midpoint = (start + end) / 2;
        List<Integer> leftList = sortListInterval(unsortedList, start, midpoint);
        List<Integer> rightList = sortListInterval(unsortedList, midpoint, end);

        ArrayList<Integer> resultList = new ArrayList<>();
        int leftPointer = 0, rightPointer = 0;

        // Merge the sorted left and right lists with two pointers
        while (leftPointer < leftList.size() || rightPointer < rightList.size()) {
            if (leftPointer == leftList.size()) { // If left list is empty, append element from right
                resultList.add(rightList.get(rightPointer));
                rightPointer++;
            } else if (rightPointer == rightList.size()) { // If right list is empty, append element from left
                resultList.add(leftList.get(leftPointer));
                leftPointer++;
            } else if (leftList.get(leftPointer) <= rightList.get(rightPointer)) { // Append smaller element from left
                resultList.add(leftList.get(leftPointer));
                leftPointer++;
            } else { // Append smaller element from right
                resultList.add(rightList.get(rightPointer));
                rightPointer++;
            }
        }

        return resultList;
    }

    public static List<Integer> sortList(List<Integer> unsortedList) {
        return sortListInterval(unsortedList, 0, unsortedList.size());
    }

    public static List<String> splitWords(String s) {
        return s.isEmpty() ? List.of() : Arrays.asList(s.split(" "));
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        List<Integer> unsortedList = splitWords(scanner.nextLine()).stream().map(Integer::parseInt).collect(Collectors.toList());
        scanner.close();
        List<Integer> res = sortList(unsortedList);
        System.out.println(res.stream().map(String::valueOf).collect(Collectors.joining(" ")));
    }
}
